export async function listTools() {
  return [
    {
      name: 'user_note',
      description: 'Store a note for a user. The note is optional and may be a string or null.',
      inputSchema: {
        type: 'object',
        properties: {
          user_id: { type: 'string' },
          note: { anyOf: [{ type: 'string' }, { type: 'null' }] },
        },
        required: ['user_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'user_note') {
    const error = new Error('Unknown tool: ' + name);
    error.code = -32602;
    throw error;
  }

  const { user_id, note } = args || {};

  if (typeof user_id !== 'string') {
    const error = new Error('user_id is required and must be a string');
    error.code = -32602;
    throw error;
  }

  if (
    note !== undefined &&
    note !== null &&
    typeof note !== 'string'
  ) {
    const error = new Error('note must be a string or null');
    error.code = -32602;
    throw error;
  }

  const known = new Set(['user_id', 'note']);
  for (const key of Object.keys(args || {})) {
    if (!known.has(key)) {
      const error = new Error('Unexpected field: ' + key);
      error.code = -32602;
      throw error;
    }
  }

  const resolvedNote = note === undefined ? null : note;

  return {
    content: [
      { type: 'text', text: JSON.stringify({ user_id, note: resolvedNote }) },
    ],
  };
}

